PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE inventory
               (
                   Date
                   TEXT,
                   Store_ID
                   TEXT,
                   Product_ID
                   TEXT,
                   Category
                   TEXT,
                   Region
                   TEXT,
                   Inventory_Level
                   INTEGER,
                   Units_Sold
                   INTEGER,
                   Units_Ordered
                   INTEGER,
                   Demand_Forecast
                   REAL,
                   Price
                   REAL,
                   Discount
                   REAL,
                   Weather_Condition
                   TEXT,
                   Holiday_Promotion
                   INTEGER,
                   Competitor_Pricing
                   REAL,
                   Seasonality
                   TEXT,
                   Lead_Time
                   INTEGER
               );
COMMIT;
